// uploads-smart: Worker API created from org-baseline (worker-api template).

interface Env {
	AI: Ai;
	UPLOADS: R2Bucket;
	API_KEY: string;
}

/** Every model call goes through the org AI Gateway with git-next cost metadata. */
export function gateway(task: string) {
	return { gateway: { id: "git-next", metadata: { developer: "git-next", repo: "uploads-smart", fork: false, agent: "app", task } } };
}

// Summaries/extraction task -> approved chores model per org catalog.
const DESCRIBE_MODEL = "@cf/zai-org/glm-5.3-flash";

// Shared bucket, namespaced by repo so keys don't collide with other services.
function r2Key(name: string): string {
	return `uploads-smart/${name}`;
}

async function describe(env: Env, name: string, body: ArrayBuffer, contentType: string): Promise<string> {
	let preview: string;
	try {
		preview = new TextDecoder("utf-8", { fatal: true }).decode(body.slice(0, 4000));
	} catch {
		preview = `[binary content, ${body.byteLength} bytes, type ${contentType || "unknown"}]`;
	}

	try {
		const result = await env.AI.run(
			DESCRIBE_MODEL,
			{
				messages: [
					{ role: "system", content: "Describe the uploaded file in exactly one concise sentence." },
					{ role: "user", content: `Filename: ${name}\nContent-Type: ${contentType || "unknown"}\n\n${preview}` },
				],
			},
			gateway("describe-upload"),
		);
		const text = (result as { response?: string }).response ?? String(result);
		return text.trim().split("\n")[0] || "No description available.";
	} catch {
		return "Description unavailable.";
	}
}

function unauthorized(): Response {
	return new Response("Unauthorized", { status: 401 });
}

export default {
	async fetch(request: Request, env: Env): Promise<Response> {
		const url = new URL(request.url);
		if (url.pathname === "/health") return Response.json({ ok: true });

		const match = url.pathname.match(/^\/files\/([^/]+)$/);
		if (!match) return new Response("Not found", { status: 404 });
		const name = decodeURIComponent(match[1]);
		const key = r2Key(name);

		if (request.method === "PUT") {
			const provided = request.headers.get("x-api-key") ?? request.headers.get("authorization")?.replace(/^Bearer\s+/i, "");
			if (!env.API_KEY || provided !== env.API_KEY) return unauthorized();

			const body = await request.arrayBuffer();
			const contentType = request.headers.get("content-type") ?? "application/octet-stream";
			const description = await describe(env, name, body, contentType);

			await env.UPLOADS.put(key, body, {
				httpMetadata: { contentType },
				customMetadata: { description },
			});

			return Response.json({ name, description }, { status: 201 });
		}

		if (request.method === "GET") {
			const object = await env.UPLOADS.get(key);
			if (!object) return new Response("Not found", { status: 404 });
			const headers = new Headers();
			object.writeHttpMetadata(headers);
			headers.set("etag", object.httpEtag);
			if (object.customMetadata?.description) headers.set("x-description", object.customMetadata.description);
			return new Response(object.body, { headers });
		}

		return new Response("Method not allowed", { status: 405 });
	},
} satisfies ExportedHandler<Env>;

wrangler.jsonc:
{
	// Generated by `git next new` from org-baseline. Secrets go in `wrangler secret put NAME` (or .dev.vars locally), never here.
	"$schema": "node_modules/wrangler/config-schema.json",
	"name": "uploads-smart",
	"main": "src/index.ts",
	"compatibility_date": "2026-10-06",
	"compatibility_flags": ["nodejs_compat"],
	"observability": { "enabled": true },
	// Workers AI only through the org gateway: pass { gateway: { id: "git-next" } } on every env.AI.run call.
	"ai": { "binding": "AI" },
	// Shared bucket from .gitnext/catalog.json; keys are namespaced "uploads-smart/<name>".
	"r2_buckets": [{ "binding": "UPLOADS", "bucket_name": "acme-shared-uploads" }]
	// Add only resources from .gitnext/catalog.json. Forks must not bind production resources.
}
